"""Ensure and maintain Coval test sets for local benchmarking."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Dict, List

from rasa.builder.copilot.mcp_server.tools.coval.client import CovalClient


@dataclass(frozen=True)
class PrunedTestCase:
    """A benchmark-managed test case removed from a test set."""

    scenario_slug: str
    test_case_id: str


async def ensure_test_set(client: CovalClient, display_name: str) -> str:
    """Return a reusable Coval test set id for ``display_name``."""
    matches = await client.list_test_sets(display_name=display_name)
    if matches and matches[0].get("id"):
        return str(matches[0]["id"])
    return await client.create_test_set(
        {
            "display_name": display_name,
            "test_set_type": "SCENARIO",
        }
    )


async def prune_scenario_test_cases(
    client: CovalClient,
    test_set_id: str,
    keep_slugs: set[str],
    *,
    existing_cases: List[Dict[str, Any]] | None = None,
) -> List[PrunedTestCase]:
    """Delete benchmark-managed test cases whose slug is not in ``keep_slugs``."""
    from rasa.builder.copilot.mcp_server.tools.coval.sync import list_test_cases_for_set

    cases = existing_cases
    if cases is None:
        cases = await list_test_cases_for_set(client, test_set_id)

    pruned: List[PrunedTestCase] = []
    for test_case in cases:
        metric_input = test_case.get("metric_input") or {}
        scenario_slug = metric_input.get("scenario_slug")
        if not scenario_slug or str(scenario_slug) in keep_slugs:
            continue
        test_case_id = test_case.get("id")
        if not test_case_id:
            continue
        await client.delete_test_case(str(test_case_id))
        pruned.append(
            PrunedTestCase(
                scenario_slug=str(scenario_slug),
                test_case_id=str(test_case_id),
            )
        )
    return pruned
